/** Builders for prooflab JSON documents. Mirrors prooflab/formats.py, so
 * files downloaded from the website verify in the CLI. */

import type { ProofStep } from "./merkle";

export const EDUCATIONAL_NOTE =
  "Educational demonstration only. Generated by Proof Without Disclosure " +
  "(website), interoperable with the prooflab CLI. Not for real-world " +
  "security use.";

function envelope(type: string, fields: Record<string, unknown>) {
  return {
    format: "prooflab",
    version: 1,
    type,
    ...fields,
    created_at: new Date().toISOString().slice(0, 19) + "+00:00",
    note: EDUCATIONAL_NOTE,
  };
}

export function commitmentDoc(commitment: string) {
  return envelope("commitment", {
    hash_function: "sha256",
    encoding: "utf8(salt_hex):utf8(secret)",
    commitment,
  });
}

export function revealDoc(secret: string, salt: string) {
  return envelope("commitment_reveal", {
    hash_function: "sha256",
    secret,
    salt,
  });
}

export function merkleProofDoc(
  item: string,
  leafHash: string,
  root: string,
  path: ProofStep[],
) {
  return envelope("merkle_proof", {
    hash_function: "sha256",
    domain_separation: "rfc6962",
    odd_rule: "promote",
    item,
    leaf_hash: leafHash,
    root,
    path,
  });
}

export function signatureDoc(
  fileName: string,
  publicKey: string,
  signature: string,
) {
  return envelope("signature", {
    algorithm: "ecdsa-p256-sha256",
    file_name: fileName,
    public_key: publicKey,
    signature,
  });
}

export function schnorrProofDoc(
  groupName: string,
  yHex: string,
  RHex: string,
  sHex: string,
  message: string,
) {
  return envelope("schnorr_proof", {
    flavor: "fiat-shamir",
    hash_function: "sha256",
    group: groupName,
    public_key: yHex,
    commitment: RHex,
    response: sHex,
    message,
  });
}

/** Trigger a JSON download entirely client-side. */
export function downloadJson(doc: unknown, filename: string) {
  const blob = new Blob([JSON.stringify(doc, null, 2) + "\n"], {
    type: "application/json",
  });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
}
